--

CREATE FUNCTION public.actor_chain_revocation_bump_authorization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    target_org   UUID;
    target_owner UUID;
BEGIN
    SELECT org_id, owner_principal_id
      INTO target_org, target_owner
      FROM public.actor_chain_journal
     WHERE revocation_id = NEW.revocation_id;
    IF target_org IS NOT NULL THEN
        PERFORM public.bump_principal_and_organization_authorization(target_org, target_owner);
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: append_job_state_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_job_state_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    transition_actor TEXT;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.state IS NOT DISTINCT FROM OLD.state THEN
        RETURN NEW;
    END IF;

    transition_actor := COALESCE(
        NULLIF(current_setting('role', true), 'none'),
        session_user::text
    );

    INSERT INTO public.job_state_transitions (
        job_id,
        from_state,
        to_state,
        state_version,
        attempt_count,
        actor,
        error_code,
        error_message
    ) VALUES (
        NEW.id,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.state END,
        NEW.state,
        NEW.state_version,
        NEW.attempt_count,
        transition_actor,
        NEW.last_error_code,
        NEW.last_error_message
    );
    RETURN NEW;
END
$$;


