--
-- Name: bump_organization_authorization_revision(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_organization_authorization_revision(target_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF target_org IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.organizations WHERE id = target_org
    ) THEN
        RETURN;
    END IF;
    INSERT INTO public.organization_authorization_revisions (org_id, revision, updated_at)
    VALUES (
        target_org,
        nextval('public.authorization_revision_sequence'),
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (org_id) DO UPDATE
       SET revision = EXCLUDED.revision,
           updated_at = EXCLUDED.updated_at;
END
$$;


