    AS $$
BEGIN
    PERFORM public.bump_organization_authorization_revision(target_org);
    PERFORM public.bump_principal_authorization_revision(target_org, target_principal);
END
$$;


--
-- Name: bump_principal_authorization_revision(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_principal_authorization_revision(target_org uuid, target_principal uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF target_org IS NULL OR target_principal IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.organizations WHERE id = target_org
    ) THEN
        RETURN;
    END IF;
    INSERT INTO public.principal_authorization_revisions (
        org_id,
        principal_id,
        revision,
        updated_at
    )
    VALUES (
        target_org,
        target_principal,
        nextval('public.authorization_revision_sequence'),
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (org_id, principal_id) DO UPDATE
       SET revision = EXCLUDED.revision,
           updated_at = EXCLUDED.updated_at;
END
$$;


--
-- Name: bump_role_authorization_revision(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_role_authorization_revision(target_role uuid, direct_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    affected_org UUID;
BEGIN
    IF direct_org IS NOT NULL THEN
        PERFORM public.bump_organization_authorization_revision(direct_org);
    END IF;
    FOR affected_org IN
        SELECT DISTINCT assignment.org_id
        FROM public.role_assignments AS assignment
        WHERE assignment.role_id = target_role
          AND assignment.org_id IS NOT NULL
    LOOP
        PERFORM public.bump_organization_authorization_revision(affected_org);
    END LOOP;
END
$$;


--
-- Name: delegation_grants_notify_decided(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delegation_grants_notify_decided() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        PERFORM pg_notify(
            'delegation_grants:' || NEW.id::text,
            json_build_object(
                'id', NEW.id,
                'status', NEW.status,
                'decided_at', NEW.decided_at,
                'reason', COALESCE(NEW.decision_reason, '')
            )::text
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_job_attempt_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_job_attempt_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.outcome IS NOT NULL OR NEW.finished_at IS NOT NULL
           OR NEW.error_code IS NOT NULL OR NEW.error_message IS NOT NULL THEN
            RAISE EXCEPTION 'new job attempts must start open without an outcome or failure'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_number IS DISTINCT FROM OLD.attempt_number
       OR NEW.worker_id IS DISTINCT FROM OLD.worker_id
       OR NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
        RAISE EXCEPTION 'job attempt identity and lease are immutable'
            USING ERRCODE = 'check_violation';
    END IF;

    IF OLD.outcome IS NOT NULL THEN
        RAISE EXCEPTION 'completed job attempt % is immutable', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.heartbeat_at < OLD.heartbeat_at THEN
        RAISE EXCEPTION 'job attempt heartbeat cannot move backwards'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: enforce_job_message_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_job_message_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'pending' OR NEW.state_version <> 0 OR NEW.attempt_count <> 0 THEN
            RAISE EXCEPTION 'new jobs must start pending at state version 0 with no attempts'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.direction IS DISTINCT FROM OLD.direction
       OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
       OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
       OR NEW.queue IS DISTINCT FROM OLD.queue
       OR NEW.topic IS DISTINCT FROM OLD.topic
       OR NEW.source IS DISTINCT FROM OLD.source
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint
       OR NEW.ordering_key IS DISTINCT FROM OLD.ordering_key
       OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
       OR NEW.payload IS DISTINCT FROM OLD.payload
       OR NEW.content_type IS DISTINCT FROM OLD.content_type
       OR NEW.attributes IS DISTINCT FROM OLD.attributes
       OR NEW.max_attempts IS DISTINCT FROM OLD.max_attempts
       OR NEW.replay_of IS DISTINCT FROM OLD.replay_of
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'job identity, routing, scope, payload, and retry policy are immutable'
            USING ERRCODE = 'check_violation';
    END IF;

    IF OLD.state IN ('succeeded', 'dead_letter', 'canceled') THEN
        RAISE EXCEPTION 'terminal job % is immutable', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.state IS DISTINCT FROM OLD.state THEN
        IF NOT public.job_state_transition_is_valid(OLD.state, NEW.state) THEN
            RAISE EXCEPTION 'invalid job state transition: % -> %', OLD.state, NEW.state
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.state = 'processing' AND NEW.attempt_count <> OLD.attempt_count + 1 THEN
            RAISE EXCEPTION 'processing transition must increment attempt_count exactly once'
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.state <> 'processing' AND NEW.attempt_count <> OLD.attempt_count THEN
            RAISE EXCEPTION 'attempt_count changes only when a job enters processing'
                USING ERRCODE = 'check_violation';
        END IF;
        NEW.state_version := OLD.state_version + 1;
    ELSIF NEW.state_version IS DISTINCT FROM OLD.state_version
       OR NEW.attempt_count IS DISTINCT FROM OLD.attempt_count THEN
        RAISE EXCEPTION 'state_version and attempt_count are state-machine owned'
            USING ERRCODE = 'check_violation';
    END IF;

    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END
$$;


--
-- Name: enqueue_job_message(text, text, uuid, uuid, text, text, text, text, text, integer, bytea, text, jsonb, smallint, integer, timestamp with time zone, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_job_message(p_direction text, p_scope_kind text, p_organization_id uuid, p_subject_id uuid, p_queue text, p_topic text, p_source text, p_idempotency_key text, p_ordering_key text, p_schema_version integer, p_payload bytea, p_content_type text, p_attributes jsonb, p_priority smallint, p_max_attempts integer, p_available_at timestamp with time zone, p_request_fingerprint bytea) RETURNS TABLE(job_id uuid, stored_fingerprint bytea, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    caller_role TEXT;
    inserted_id UUID;
BEGIN
    caller_role := COALESCE(
        NULLIF(current_setting('role', true), 'none'),
        session_user::text
    );

    IF caller_role = 'app_tenant' THEN
        IF p_direction <> 'outbox' THEN
            RAISE EXCEPTION 'request traffic may enqueue outbox work only'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
        IF NOT (
            (
                p_scope_kind = 'tenant'
                AND p_organization_id = NULLIF(
                    current_setting('app.current_org_id', true), ''
                )::uuid
                AND p_subject_id IS NULL
            )
            OR (
                p_scope_kind = 'subject'
                AND p_subject_id = NULLIF(
                    current_setting('app.current_user_id', true), ''
                )::uuid
                AND p_organization_id IS NULL
            )
        ) THEN
            RAISE EXCEPTION 'job scope does not match the signed request scope'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
    ELSIF caller_role = 'app_control_plane' THEN
        IF p_direction <> 'outbox'
           OR p_scope_kind <> 'global'
           OR p_organization_id IS NOT NULL
           OR p_subject_id IS NOT NULL THEN
            RAISE EXCEPTION 'control-plane traffic may enqueue global outbox work only'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
    ELSIF caller_role <> 'app_job_worker' THEN
        RAISE EXCEPTION 'role % cannot enqueue jobs', caller_role
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO public.job_messages (
        direction,
        scope_kind,
        organization_id,
        subject_id,
        queue,
        topic,
        source,
        idempotency_key,
        request_fingerprint,
        ordering_key,
        schema_version,
        payload,
        content_type,
        attributes,
        priority,
        max_attempts,
        available_at
    ) VALUES (
        p_direction,
        p_scope_kind,
        p_organization_id,
        p_subject_id,
        p_queue,
        p_topic,
        p_source,
        p_idempotency_key,
        p_request_fingerprint,
        p_ordering_key,
        p_schema_version,
        p_payload,
        p_content_type,
        p_attributes,
        p_priority,
        p_max_attempts,
        COALESCE(p_available_at, CURRENT_TIMESTAMP)
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO inserted_id;

    IF inserted_id IS NOT NULL THEN
        RETURN QUERY SELECT inserted_id, p_request_fingerprint, TRUE;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT message.id, message.request_fingerprint, FALSE
    FROM public.job_messages AS message
    WHERE message.direction = p_direction
      AND message.scope_kind = p_scope_kind
      AND message.organization_id IS NOT DISTINCT FROM p_organization_id
      AND message.subject_id IS NOT DISTINCT FROM p_subject_id
      AND message.queue = p_queue
      AND message.source = p_source
      AND message.idempotency_key = p_idempotency_key;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'job idempotency conflict could not be resolved'
            USING ERRCODE = 'serialization_failure';
    END IF;
END
$$;


--
-- Name: invalidate_authorization_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_authorization_sessions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'users' THEN
        IF NEW.status IS DISTINCT FROM OLD.status THEN
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = CASE
                       WHEN NEW.status = 'active' THEN 'user_status_changed'
                       ELSE 'user_not_active'
                   END
             WHERE user_id = NEW.uuid
               AND revoked_at IS NULL;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_TABLE_NAME = 'organization_members' THEN
        IF TG_OP = 'INSERT' THEN
            -- An org-less session must not silently acquire newly granted
            -- tenant authority on its next refresh.
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'organization_membership_added'
             WHERE user_id = NEW.user_id
               AND org_id IS NULL
               AND revoked_at IS NULL;
            RETURN NEW;
        END IF;

        IF TG_OP = 'DELETE' THEN
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'organization_membership_revoked'
             WHERE user_id = OLD.user_id
               AND (org_id = OLD.org_id OR org_id IS NULL)
               AND revoked_at IS NULL;
            RETURN OLD;
        END IF;

        IF NEW.user_id IS DISTINCT FROM OLD.user_id
           OR NEW.org_id IS DISTINCT FROM OLD.org_id
           OR NEW.role IS DISTINCT FROM OLD.role THEN
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'organization_membership_changed'
             WHERE user_id = OLD.user_id
               AND (org_id = OLD.org_id OR org_id IS NULL)
               AND revoked_at IS NULL;

            IF NEW.user_id IS DISTINCT FROM OLD.user_id
               OR NEW.org_id IS DISTINCT FROM OLD.org_id THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'organization_membership_changed'
                 WHERE user_id = NEW.user_id
                   AND (org_id = NEW.org_id OR org_id IS NULL)
                   AND revoked_at IS NULL;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_TABLE_NAME = 'platform_admins' THEN
        IF TG_OP = 'INSERT' THEN
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'platform_role_changed'
             WHERE user_id = NEW.user_id
               AND revoked_at IS NULL;
            RETURN NEW;
        END IF;

        IF TG_OP = 'DELETE' THEN
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'platform_role_changed'
             WHERE user_id = OLD.user_id
               AND revoked_at IS NULL;
            RETURN OLD;
        END IF;

        IF NEW.user_id IS DISTINCT FROM OLD.user_id
           OR NEW.platform_role IS DISTINCT FROM OLD.platform_role THEN
            IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'platform_role_changed'
                 WHERE user_id = OLD.user_id
                   AND revoked_at IS NULL;
            END IF;
            UPDATE public.sessions
               SET revoked_at = CURRENT_TIMESTAMP,
                   revoked_reason = 'platform_role_changed'
             WHERE user_id = NEW.user_id
               AND revoked_at IS NULL;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_TABLE_NAME = 'mfa_devices' THEN
        IF TG_OP = 'INSERT' THEN
            IF NEW.verified_at IS NOT NULL THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'mfa_enrollment_changed'
                 WHERE user_id = NEW.user_id
                   AND revoked_at IS NULL;
            END IF;
            RETURN NEW;
        END IF;

        IF TG_OP = 'DELETE' THEN
            IF OLD.verified_at IS NOT NULL THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'mfa_enrollment_changed'
                 WHERE user_id = OLD.user_id
                   AND revoked_at IS NULL;
            END IF;
            RETURN OLD;
        END IF;

        IF NEW.user_id IS DISTINCT FROM OLD.user_id
           OR (NEW.verified_at IS NULL) IS DISTINCT FROM (OLD.verified_at IS NULL) THEN
            IF OLD.verified_at IS NOT NULL THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'mfa_enrollment_changed'
                 WHERE user_id = OLD.user_id
                   AND revoked_at IS NULL;
            END IF;
            IF NEW.verified_at IS NOT NULL THEN
                UPDATE public.sessions
                   SET revoked_at = CURRENT_TIMESTAMP,
                       revoked_reason = 'mfa_enrollment_changed'
                 WHERE user_id = NEW.user_id
                   AND revoked_at IS NULL;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'unsupported authorization invalidation source: %', TG_TABLE_NAME;
END
$$;


--
-- Name: invalidate_scoped_role_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_scoped_role_sessions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE')
       AND OLD.subject_kind = 'principal'
       AND OLD.scope IS NOT NULL
       AND OLD.org_id IS NOT NULL THEN
        UPDATE public.sessions
           SET revoked_at = CURRENT_TIMESTAMP,
               revoked_reason = 'scoped_role_changed'
         WHERE user_id = OLD.subject_id
           AND (org_id = OLD.org_id OR org_id IS NULL)
           AND revoked_at IS NULL;
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE')
       AND NEW.subject_kind = 'principal'
       AND NEW.scope IS NOT NULL
       AND NEW.org_id IS NOT NULL THEN
        UPDATE public.sessions
           SET revoked_at = CURRENT_TIMESTAMP,
               revoked_reason = 'scoped_role_changed'
         WHERE user_id = NEW.subject_id
           AND (org_id = NEW.org_id OR org_id IS NULL)
           AND revoked_at IS NULL;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: job_state_transition_is_valid(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_state_transition_is_valid(from_state text, to_state text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT CASE from_state
        WHEN 'pending' THEN to_state IN ('processing', 'canceled')
        WHEN 'processing' THEN to_state IN ('retrying', 'succeeded', 'dead_letter')
        WHEN 'retrying' THEN to_state IN ('processing', 'canceled')
        ELSE FALSE
    END
$$;


--
-- Name: organization_eligible_administrators(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_eligible_administrators(p_org_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT member.user_id
    FROM public.organization_members AS member
    JOIN public.users AS u
      ON u.uuid = member.user_id
    WHERE member.org_id = p_org_id
      AND member.org_id::text = pg_catalog.current_setting('app.current_org_id', true)
      AND member.role IN ('owner', 'admin')
      AND u.status = 'active'
$$;


--
-- Name: organization_member_primary_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_member_primary_email(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT u.primary_email
    FROM public.users AS u
    JOIN public.organization_members AS member
      ON member.user_id = u.uuid
    WHERE u.uuid = p_user_id
      AND member.org_id::text = pg_catalog.current_setting('app.current_org_id', true)
      AND u.status <> 'deleted'
    LIMIT 1
$$;


--
-- Name: publish_domain_event(uuid, text, text, text, timestamp with time zone, text, text, text, bytea, uuid, text, text, text, text, text, text, text, integer, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_domain_event(p_id uuid, p_type text, p_source text, p_subject text, p_event_time timestamp with time zone, p_specversion text, p_datacontenttype text, p_dataschema text, p_data bytea, p_tenant_id uuid, p_boundary_id text, p_partition_key text, p_correlation_id text, p_causation_id text, p_actor_principal_id text, p_owner_principal_id text, p_traceparent text, p_schema_version integer, p_request_fingerprint bytea) RETURNS TABLE(event_id uuid, stored_fingerprint bytea, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    caller_role TEXT;
    inserted_id UUID;
BEGIN
    caller_role := COALESCE(
        NULLIF(current_setting('role', true), 'none'),
        session_user::text
    );

    IF caller_role = 'app_tenant' THEN
        -- IS DISTINCT FROM, not <>: a transaction that never set app.current_org_id
        -- (a user-scoped one, which runs as app_tenant and sets only
        -- app.current_user_id) leaves the setting NULL, and `p_tenant_id <> NULL`
        -- is NULL, not TRUE — so a plain comparison lets that transaction publish
        -- for any tenant it names. The guard has to fail closed on an absent scope.
        IF p_tenant_id IS NULL
           OR p_tenant_id IS DISTINCT FROM NULLIF(current_setting('app.current_org_id', true), '')::uuid THEN
            RAISE EXCEPTION 'event tenant does not match the signed request scope'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
    ELSIF caller_role = 'app_control_plane' THEN
        -- The control plane publishes on behalf of a tenant. A platform-admin
        -- mutation writes its audit record with RLS bypassed, and that record's
        -- external domain event is what an outbound webhook subscription is
        -- fanned out from, so refusing a tenant here would silently stop
        -- delivering every privileged action to the endpoints subscribed to it.
        -- The role already writes any tenant's audit rows; publishing the
        -- matching event is the same authority, and the relay applies the tenant
        -- gate again when it resolves subscriptions.
        NULL;
    ELSIF caller_role <> 'app_job_worker' THEN
        RAISE EXCEPTION 'role % cannot publish domain events', caller_role
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Serialize concurrent publishes within one partition so that the identity
    -- seq assigned below is handed out in commit order, not merely in insert
    -- order. The lock is transaction-scoped: it is held until the producer's
    -- transaction commits or rolls back, which is exactly the window in which a
    -- competing producer could otherwise take a higher seq and commit first.
    -- Ordering is a per-partition guarantee, so the lock is per-partition; a
    -- platform event with no partition key is unordered by construction
    -- (eventOrdering returns no ordering key for it) and takes no lock, so it
    -- never serializes against anything.
    IF COALESCE(p_partition_key, '') <> '' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('events:' || p_partition_key, 0));
    END IF;

    INSERT INTO public.domain_events (
        id, type, source, subject, event_time, specversion, datacontenttype,
        dataschema, data, tenant_id, boundary_id, partition_key, correlation_id,
        causation_id, actor_principal_id, owner_principal_id, traceparent,
        schema_version, request_fingerprint
    ) VALUES (
        p_id, p_type, p_source, COALESCE(p_subject, ''), p_event_time,
        COALESCE(p_specversion, ''), COALESCE(p_datacontenttype, ''),
        COALESCE(p_dataschema, ''), COALESCE(p_data, ''::bytea), p_tenant_id,
        COALESCE(p_boundary_id, ''), COALESCE(p_partition_key, ''),
        COALESCE(p_correlation_id, ''), COALESCE(p_causation_id, ''),
        COALESCE(p_actor_principal_id, ''), COALESCE(p_owner_principal_id, ''),
        COALESCE(p_traceparent, ''), COALESCE(p_schema_version, 1),
        p_request_fingerprint
    )
    ON CONFLICT (id) DO NOTHING
    RETURNING id INTO inserted_id;

    IF inserted_id IS NOT NULL THEN
        RETURN QUERY SELECT inserted_id, p_request_fingerprint, TRUE;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT existing.id, existing.request_fingerprint, FALSE
    FROM public.domain_events AS existing
    WHERE existing.id = p_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'domain event idempotency conflict could not be resolved'
            USING ERRCODE = 'serialization_failure';
    END IF;
END
$$;


--
-- Name: record_delivery_event(text, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_delivery_event(p_provider text, p_event_id text, p_provider_email_id text, p_event_type text, p_delivery_status text, p_event_created_at timestamp with time zone, p_invitation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    inserted_count BIGINT := 0;
BEGIN
    INSERT INTO public.email_delivery_events (
        provider,
        event_id,
        provider_email_id,
        event_type,
        delivery_status,
        invitation_id,
        event_created_at
    )
    VALUES (
        p_provider,
        p_event_id,
        p_provider_email_id,
        p_event_type,
        p_delivery_status,
        p_invitation_id,
        p_event_created_at
    )
    ON CONFLICT (provider, event_id) DO NOTHING;

    GET DIAGNOSTICS inserted_count = ROW_COUNT;
    IF inserted_count = 0 OR p_invitation_id IS NULL OR p_delivery_status IS NULL THEN
        RETURN inserted_count = 1;
    END IF;

    UPDATE public.invitations
    SET delivery_status = p_delivery_status
    WHERE id = p_invitation_id
      AND CASE delivery_status
            WHEN 'disabled' THEN 0
            WHEN 'queued' THEN 1
            WHEN 'sent' THEN 2
            WHEN 'delivered' THEN 3
            WHEN 'bounced' THEN 4
            WHEN 'complained' THEN 5
            ELSE -1
          END
          <=
          CASE p_delivery_status
            WHEN 'sent' THEN 2
            WHEN 'delivered' THEN 3
            WHEN 'bounced' THEN 4
            WHEN 'complained' THEN 5
            ELSE -1
          END;

    RETURN inserted_count = 1;
END;
$$;


--
-- Name: record_membership_integrity_findings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_membership_integrity_findings() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    outstanding integer;
BEGIN
    -- An inventory has to see every organization, and organizations,
    -- organization_members and users (administrator eligibility depends on
    -- identity status) are all FORCE ROW LEVEL SECURITY — which subjects the
    -- table owner to their policies as well. Those policies scope to
    -- app.current_org_id and carry no bypass clause (a session setting must
    -- never grant RLS authority; the role-hardening suite asserts no live
    -- policy reads one). A caller that does not span organizations therefore
    -- reads zero rows, records nothing, and returns 0 — a result identical to a
    -- healthy platform and one nobody would think to question. Refuse instead.
    IF NOT EXISTS (
        SELECT 1 FROM pg_roles
        WHERE rolname = current_user AND (rolbypassrls OR rolsuper)
    ) THEN
        RAISE EXCEPTION
            'record_membership_integrity_findings() must run as a role that spans every organization; % does not, and would record an empty backlog',
            current_user
            USING HINT = 'assume the control plane first: SET ROLE app_control_plane';
    END IF;

    WITH org_administration AS (
        -- One pass over the membership graph, so every finding below is decided
        -- from the same per-organization facts rather than from repeated
        -- correlated subqueries that could drift apart.
        --
        -- "Eligible" is migration 133's definition, deliberately reproduced
        -- rather than approximated: role IN ('owner','admin') AND the identity
        -- is active. findIdentity admits only active identities and DeleteUser
        -- is a soft delete that leaves the membership row standing, so counting
        -- every administrative row regardless of identity status reports an
        -- organization healthy when nobody can actually sign in and administer
        -- it. That organization is precisely the backlog this inventory exists
        -- to size. Migration 133's organization_eligible_administrators() is
        -- not reused here: it is SECURITY DEFINER scoped to app.current_org_id,
        -- so it answers for one tenant, and this is a cross-tenant inventory.
        SELECT
            o.id       AS org_id,
            o.owner_id AS owner_id,
            (
                SELECT om.role FROM organization_members om
                WHERE om.org_id = o.id AND om.user_id = o.owner_id
            ) AS owner_membership_role,
            (
                SELECT u.status::text FROM users u WHERE u.uuid = o.owner_id
            ) AS owner_status,
            count(*) FILTER (
                WHERE member.role IN ('owner', 'admin')
            ) AS administrative_members,
            count(*) FILTER (
                WHERE member.role IN ('owner', 'admin') AND holder.status = 'active'
            ) AS eligible_administrators,
            count(*) FILTER (
                WHERE member.role IN ('owner', 'admin') AND holder.status = 'active'
                  AND member.user_id = o.owner_id
            ) AS owner_is_eligible
        FROM organizations o
        LEFT JOIN organization_members member ON member.org_id = o.id
        LEFT JOIN users holder ON holder.uuid = member.user_id
        GROUP BY o.id, o.owner_id
    ),
    current_findings AS (
        -- The findings are mutually exclusive by construction: one CASE over
        -- one row per organization can only ever yield one of them. The
        -- previous shape kept three disjoint WHERE clauses in step by hand,
        -- which is the kind of agreement that silently stops holding. An
        -- organization is therefore never counted twice, so the row count this
        -- function returns is an organization count -- the number an operator
        -- sizes the repair from.
        SELECT
            org_id,
            CASE
                -- No administrative membership exists at all. Repairing this
                -- means choosing a user and granting them authority.
                WHEN administrative_members = 0
                    THEN 'organization_without_administrator'
                -- Administrative memberships exist, but every holder is
                -- deleted, suspended or otherwise not active. Materially
                -- cheaper to repair -- reactivating one identity may be
                -- enough -- and a different operator decision, which is why it
                -- is reported apart from the case above rather than folded in.
                WHEN eligible_administrators = 0
                    THEN 'organization_without_an_eligible_administrator'
                -- Somebody eligible can administer this organization, but it is
                -- not the owner of record: either the owner holds no
                -- administrative membership, or holds one whose identity is not
                -- active. owner_status and membership_role tell those apart.
                ELSE 'owner_of_record_is_not_an_administrator'
            END AS finding,
            jsonb_build_object(
                'owner_id', owner_id,
                'membership_role', owner_membership_role,
                'owner_status', owner_status,
                'administrative_members', administrative_members,
                'eligible_administrators', eligible_administrators
            ) AS detail
        FROM org_administration
        WHERE administrative_members  = 0
           OR eligible_administrators = 0
           OR owner_is_eligible       = 0
    ),
    resolved AS (
        DELETE FROM membership_integrity_findings f
        WHERE NOT EXISTS (
            SELECT 1 FROM current_findings c
            WHERE c.org_id = f.org_id AND c.finding = f.finding
        )
    )
    INSERT INTO membership_integrity_findings (org_id, finding, detail)
    SELECT org_id, finding, detail FROM current_findings
    ON CONFLICT (org_id, finding) DO UPDATE SET detail = EXCLUDED.detail;

    SELECT count(*) INTO outstanding FROM membership_integrity_findings;
    RETURN outstanding;
END
$$;


--
-- Name: replay_job_message(uuid, text, timestamp with time zone, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_job_message(p_source_job_id uuid, p_idempotency_key text, p_available_at timestamp with time zone, p_request_fingerprint bytea) RETURNS TABLE(job_id uuid, stored_fingerprint bytea, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    caller_role TEXT;
    source_message public.job_messages%ROWTYPE;
    inserted_id UUID;
BEGIN
    caller_role := COALESCE(
        NULLIF(current_setting('role', true), 'none'),
        session_user::text
    );
    IF caller_role <> 'app_job_worker' THEN
        RAISE EXCEPTION 'role % cannot replay jobs', caller_role
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO source_message
    FROM public.job_messages
    WHERE id = p_source_job_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'source job does not exist'
            USING ERRCODE = 'no_data_found';
    END IF;
    IF source_message.state <> 'dead_letter' THEN
        RAISE EXCEPTION 'only dead-lettered jobs may be replayed'
            USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;

    INSERT INTO public.job_messages (
        direction,
        scope_kind,
        organization_id,
        subject_id,
        queue,
        topic,
        source,
        idempotency_key,
        request_fingerprint,
        ordering_key,
        schema_version,
        payload,
        content_type,
        attributes,
        priority,
        max_attempts,
        available_at,
        replay_of
    ) VALUES (
        source_message.direction,
        source_message.scope_kind,
        source_message.organization_id,
        source_message.subject_id,
        source_message.queue,
        source_message.topic,
        source_message.source,
        p_idempotency_key,
        p_request_fingerprint,
        source_message.ordering_key,
        source_message.schema_version,
        source_message.payload,
        source_message.content_type,
        source_message.attributes,
        source_message.priority,
        source_message.max_attempts,
        COALESCE(p_available_at, CURRENT_TIMESTAMP),
        source_message.id
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO inserted_id;

    IF inserted_id IS NOT NULL THEN
        RETURN QUERY SELECT inserted_id, p_request_fingerprint, TRUE;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT message.id, message.request_fingerprint, FALSE
    FROM public.job_messages AS message
    WHERE message.direction = source_message.direction
      AND message.scope_kind = source_message.scope_kind
      AND message.organization_id IS NOT DISTINCT FROM source_message.organization_id
      AND message.subject_id IS NOT DISTINCT FROM source_message.subject_id
      AND message.queue = source_message.queue
      AND message.source = source_message.source
      AND message.idempotency_key = p_idempotency_key;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'job replay idempotency conflict could not be resolved'
            USING ERRCODE = 'serialization_failure';
    END IF;
END
$$;


--
-- Name: settings_jsonb_deep_merge(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settings_jsonb_deep_merge(stored jsonb, patch jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT CASE
        WHEN jsonb_typeof(stored) = 'object' AND jsonb_typeof(patch) = 'object'
        THEN COALESCE((
            SELECT jsonb_object_agg(
                keys.key,
                CASE
                    WHEN stored ? keys.key AND patch ? keys.key
                    THEN public.settings_jsonb_deep_merge(
                        stored -> keys.key,
                        patch -> keys.key
                    )
                    WHEN patch ? keys.key
                    THEN patch -> keys.key
                    ELSE stored -> keys.key
                END
            )
            FROM (
                SELECT jsonb_object_keys(stored) AS key
                UNION
                SELECT jsonb_object_keys(patch) AS key
            ) AS keys
        ), '{}'::jsonb)
        ELSE patch
    END
$$;


--
-- Name: settings_jsonb_delete_path(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settings_jsonb_delete_path(stored jsonb, path text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    child JSONB;
    key TEXT;
BEGIN
    IF COALESCE(array_length(path, 1), 0) = 0
       OR jsonb_typeof(stored) <> 'object' THEN
        RETURN stored;
    END IF;
    key := path[1];
    IF NOT stored ? key THEN
        RETURN stored;
    END IF;
    IF array_length(path, 1) = 1 THEN
        RETURN stored - key;
    END IF;
    child := public.settings_jsonb_delete_path(
        stored -> key,
        path[2:array_length(path, 1)]
    );
    IF child = '{}'::jsonb THEN
        RETURN stored - key;
    END IF;
    RETURN jsonb_set(stored, ARRAY[key], child);
END
$$;


--
-- Name: settings_jsonb_delete_paths(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settings_jsonb_delete_paths(stored jsonb, paths text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    result JSONB := stored;
    setting_path TEXT;
BEGIN
    FOREACH setting_path IN ARRAY paths LOOP
        result := public.settings_jsonb_delete_path(
            result,
            string_to_array(setting_path, '.')
        );
    END LOOP;
    RETURN result;
END
$$;


--
-- Name: sync_human_principal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_human_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.principals (
            id,
            kind,
            display_name,
            org_id,
            agent_identifier,
            created_at
        )
        VALUES (
            NEW.uuid,
            'human',
            NEW.primary_email,
            NULL,
            NULL,
            NEW.created_at
        )
        ON CONFLICT (id) DO NOTHING;
        RETURN NEW;
    END IF;

    UPDATE public.principals
       SET display_name = NEW.primary_email,
           revoked_at = CASE
               WHEN NEW.status IN ('inactive', 'suspended', 'deleted')
                   THEN COALESCE(revoked_at, CURRENT_TIMESTAMP)
               ELSE revoked_at
           END,
           revoked_reason = CASE
               WHEN NEW.status IN ('inactive', 'suspended', 'deleted')
                   THEN COALESCE(revoked_reason, 'user_status_' || NEW.status::text)
               ELSE revoked_reason
           END
     WHERE id = NEW.uuid
       AND kind = 'human';
    RETURN NEW;
END
$$;


--
-- Name: sync_webhook_event_subscriptions(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_webhook_event_subscriptions(p_org_id uuid, p_webhook_subscription_id uuid, p_type_patterns text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    caller_role TEXT;
    owner_org   UUID;
BEGIN
    caller_role := COALESCE(
        NULLIF(current_setting('role', true), 'none'),
        session_user::text
    );

    IF caller_role = 'app_tenant' THEN
        IF p_org_id IS NULL
           OR p_org_id IS DISTINCT FROM NULLIF(current_setting('app.current_org_id', true), '')::uuid THEN
            RAISE EXCEPTION 'webhook subscription org does not match the signed request scope'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
    ELSIF caller_role NOT IN ('app_control_plane', 'app_job_worker') THEN
        RAISE EXCEPTION 'role % cannot manage webhook event subscriptions', caller_role
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- The endpoint must belong to the org the subscriptions are being bound to,
    -- so a caller holding one org's scope cannot attach a subscription to another
    -- org's endpoint by naming its id.
    SELECT org_id INTO owner_org
    FROM public.webhook_subscriptions
    WHERE id = p_webhook_subscription_id;
    IF owner_org IS NULL OR owner_org <> p_org_id THEN
        RAISE EXCEPTION 'webhook subscription does not belong to this organization'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    DELETE FROM public.event_subscriptions
    WHERE webhook_subscription_id = p_webhook_subscription_id
      AND type_pattern <> ALL(COALESCE(p_type_patterns, ARRAY[]::text[]));

    INSERT INTO public.event_subscriptions
        (subscriber_principal_id, type_pattern, queue, delivery, org_id, webhook_subscription_id)
    SELECT NULL::uuid, pattern, 'webhooks', 'webhook', p_org_id, p_webhook_subscription_id
    FROM unnest(COALESCE(p_type_patterns, ARRAY[]::text[])) AS pattern
    ON CONFLICT DO NOTHING;
END
$$;


