    disabled_reason text,
    CONSTRAINT principals_agent_identifier_consistency CHECK ((((kind = 'agent'::text) AND (agent_identifier IS NOT NULL) AND (agent_identifier <> ''::text)) OR ((kind <> 'agent'::text) AND (agent_identifier IS NULL)))),
    CONSTRAINT principals_ceiling_agent_only CHECK (((kind = 'agent'::text) OR ((cardinality(allowed_audiences) = 0) AND (cardinality(allowed_scopes) = 0)))),
    CONSTRAINT principals_disabled_consistency CHECK ((((disabled_at IS NULL) AND (disabled_reason IS NULL)) OR ((disabled_at IS NOT NULL) AND (kind = 'agent'::text)))),
    CONSTRAINT principals_kind_valid CHECK ((kind = ANY (ARRAY['human'::text, 'service'::text, 'agent'::text]))),
    CONSTRAINT principals_org_scope CHECK ((((kind = 'human'::text) AND (org_id IS NULL)) OR ((kind = ANY (ARRAY['service'::text, 'agent'::text])) AND (org_id IS NOT NULL)))),
    CONSTRAINT principals_revoked_reason_consistency CHECK ((((revoked_at IS NULL) AND (revoked_reason IS NULL)) OR (revoked_at IS NOT NULL)))
);

