--
-- Name: delegation_grants_recent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.delegation_grants_recent AS
 SELECT g.id,
    g.org_id,
    g.kind,
    g.status,
    g.action,
    g.resource,
    g.resource_id,
    g.justification,
    g.risk_level,
    g.created_at,
    g.decided_at,
    g.expires_at,
    g.decision_reason,
    g.minted_token_id,
    (g.request_context ->> 'via_pattern'::text) AS via_pattern,
    g.actor_principal_id,
    actor.display_name AS actor_display_name,
    actor.kind AS actor_kind,
    actor.agent_identifier AS actor_agent_identifier,
    g.grantor_principal_id,
    grantor.display_name AS grantor_display_name,
    grantor.kind AS grantor_kind
   FROM ((public.delegation_grants g
     JOIN public.principals actor ON ((actor.id = g.actor_principal_id)))
     LEFT JOIN public.principals grantor ON ((grantor.id = g.grantor_principal_id)))
  WHERE (g.created_at > (CURRENT_TIMESTAMP - '7 days'::interval));


--
-- Name: VIEW delegation_grants_recent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.delegation_grants_recent IS 'M9 audit view: last 7 days of delegation grants with actor/grantor names denormalized. Inherits RLS from delegation_grants.';


--
-- Name: delegation_pattern_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.delegation_pattern_usage AS
 SELECT g.id,
    g.org_id,
    g.actor_principal_id,
    actor.display_name AS actor_display_name,
    g.grantor_principal_id,
    grantor.display_name AS grantor_display_name,
    g.action_pattern,
    g.resource_pattern,
    g.use_count,
    g.max_uses,
        CASE
            WHEN (g.max_uses IS NULL) THEN NULL::numeric
            WHEN (g.max_uses = 0) THEN NULL::numeric
            ELSE round(((100.0 * (g.use_count)::numeric) / (g.max_uses)::numeric), 1)
        END AS usage_pct,
    g.status,
    g.created_at,
    g.expires_at
   FROM ((public.delegation_grants g
     JOIN public.principals actor ON ((actor.id = g.actor_principal_id)))
     LEFT JOIN public.principals grantor ON ((grantor.id = g.grantor_principal_id)))
  WHERE (g.kind = 'pattern'::text);


--
-- Name: VIEW delegation_pattern_usage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.delegation_pattern_usage IS 'M9 audit view: pattern-grant burn-rate (use_count / max_uses). usage_pct is NULL when max_uses is null/zero.';


--
-- Name: delegation_stats_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.delegation_stats_daily AS
 SELECT org_id,
    date_trunc('day'::text, created_at) AS day,
    status,
    risk_level,
    count(*) AS count,
    count(*) FILTER (WHERE (request_context ? 'via_pattern'::text)) AS auto_approved_count
   FROM public.delegation_grants
  WHERE (created_at > (CURRENT_TIMESTAMP - '90 days'::interval))
  GROUP BY org_id, (date_trunc('day'::text, created_at)), status, risk_level;


--
-- Name: VIEW delegation_stats_daily; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.delegation_stats_daily IS 'M9 audit view: 90-day delegation counts grouped by day/status/risk. auto_approved_count splits out via_pattern grants.';


