    CONSTRAINT job_attempts_clock_check CHECK (((heartbeat_at >= started_at) AND ((finished_at IS NULL) OR (finished_at >= started_at)))),
    CONSTRAINT job_attempts_completion_check CHECK ((((outcome IS NULL) = (finished_at IS NULL)) AND ((outcome IS NOT NULL) OR ((error_code IS NULL) AND (error_message IS NULL))) AND ((outcome <> ALL (ARRAY['retryable_failure'::text, 'permanent_failure'::text, 'lease_expired'::text])) OR (error_code IS NOT NULL)))),
    CONSTRAINT job_attempts_failure_check CHECK ((((error_code IS NULL) OR (error_code ~ '^[a-z][a-z0-9_.-]{0,127}$'::text)) AND ((error_message IS NULL) OR (length(error_message) <= 4096)) AND ((error_message IS NULL) OR (error_code IS NOT NULL)))),
    CONSTRAINT job_attempts_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT job_attempts_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['succeeded'::text, 'retryable_failure'::text, 'permanent_failure'::text, 'lease_expired'::text, 'canceled'::text])))),
    CONSTRAINT job_attempts_worker_check CHECK (((length(worker_id) >= 1) AND (length(worker_id) <= 255)))
);


--
-- Name: job_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.job_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    direction text NOT NULL,
    scope_kind text NOT NULL,
    organization_id uuid,
    subject_id uuid,
    queue text NOT NULL,
    topic text NOT NULL,
    source text NOT NULL,
    idempotency_key text NOT NULL,
    request_fingerprint bytea NOT NULL,
    ordering_key text,
    schema_version integer DEFAULT 1 NOT NULL,
    payload bytea NOT NULL,
    content_type text DEFAULT 'application/json'::text NOT NULL,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    priority smallint DEFAULT 0 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 8 NOT NULL,
    lease_owner text,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    available_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_attempt_at timestamp with time zone,
    completed_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    replay_of uuid,
    state_version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    enqueue_seq bigint NOT NULL,
    CONSTRAINT job_messages_attempts_check CHECK (((attempt_count >= 0) AND ((max_attempts >= 1) AND (max_attempts <= 100)) AND (attempt_count <= max_attempts) AND ((state <> ALL (ARRAY['processing'::text, 'retrying'::text, 'succeeded'::text, 'dead_letter'::text])) OR (attempt_count > 0)) AND ((state <> 'pending'::text) OR (attempt_count = 0)) AND ((state <> 'retrying'::text) OR (attempt_count < max_attempts)))),
    CONSTRAINT job_messages_attributes_check CHECK (((jsonb_typeof(attributes) = 'object'::text) AND (octet_length((attributes)::text) <= 65536))),
    CONSTRAINT job_messages_content_type_check CHECK (((length(content_type) >= 1) AND (length(content_type) <= 255))),
    CONSTRAINT job_messages_direction_check CHECK ((direction = ANY (ARRAY['inbox'::text, 'outbox'::text]))),
    CONSTRAINT job_messages_failure_check CHECK ((((last_error_code IS NULL) OR (last_error_code ~ '^[a-z][a-z0-9_.-]{0,127}$'::text)) AND ((last_error_message IS NULL) OR (length(last_error_message) <= 4096)) AND ((last_error_message IS NULL) OR (last_error_code IS NOT NULL)) AND ((state <> ALL (ARRAY['retrying'::text, 'dead_letter'::text])) OR (last_error_code IS NOT NULL)))),
    CONSTRAINT job_messages_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 255))),
    CONSTRAINT job_messages_lease_check CHECK ((((state = 'processing'::text) AND (lease_owner IS NOT NULL) AND ((length(lease_owner) >= 1) AND (length(lease_owner) <= 255)) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (heartbeat_at IS NOT NULL)) OR ((state <> 'processing'::text) AND (lease_owner IS NULL) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (heartbeat_at IS NULL)))),
    CONSTRAINT job_messages_ordering_key_check CHECK (((ordering_key IS NULL) OR ((length(ordering_key) >= 1) AND (length(ordering_key) <= 255)))),
    CONSTRAINT job_messages_payload_size_check CHECK ((octet_length(payload) <= 1048576)),
    CONSTRAINT job_messages_priority_check CHECK (((priority >= '-100'::integer) AND (priority <= 100))),
    CONSTRAINT job_messages_queue_check CHECK ((queue ~ '^[a-z][a-z0-9_.-]{0,127}$'::text)),
    CONSTRAINT job_messages_replay_check CHECK (((replay_of IS NULL) OR (replay_of <> id))),
    CONSTRAINT job_messages_request_fingerprint_check CHECK ((octet_length(request_fingerprint) = 32)),
    CONSTRAINT job_messages_schema_version_check CHECK ((schema_version > 0)),
    CONSTRAINT job_messages_scope_check CHECK ((((scope_kind = 'tenant'::text) AND (organization_id IS NOT NULL) AND (subject_id IS NULL)) OR ((scope_kind = 'subject'::text) AND (organization_id IS NULL) AND (subject_id IS NOT NULL)) OR ((scope_kind = 'global'::text) AND (organization_id IS NULL) AND (subject_id IS NULL)))),
    CONSTRAINT job_messages_source_check CHECK ((source ~ '^[a-z][a-z0-9_.:/-]{0,254}$'::text)),
    CONSTRAINT job_messages_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'processing'::text, 'retrying'::text, 'succeeded'::text, 'dead_letter'::text, 'canceled'::text]))),
    CONSTRAINT job_messages_state_version_check CHECK ((state_version >= 0)),
    CONSTRAINT job_messages_terminal_timestamps_check CHECK ((((state = ANY (ARRAY['succeeded'::text, 'canceled'::text])) = (completed_at IS NOT NULL)) AND ((state = 'dead_letter'::text) = (dead_lettered_at IS NOT NULL)))),
    CONSTRAINT job_messages_topic_check CHECK ((topic ~ '^[a-z][a-z0-9_.-]{0,254}$'::text))
);

