    CONSTRAINT waitlist_entries_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'verified'::text, 'approved'::text, 'invited'::text, 'converted'::text, 'rejected'::text, 'unsubscribed'::text])))
);

ALTER TABLE ONLY public.waitlist_entries FORCE ROW LEVEL SECURITY;


--
-- Name: webauthn_ceremonies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webauthn_ceremonies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token_hash text NOT NULL,
    user_id uuid NOT NULL,
    mfa_login_transaction_id uuid,
    ceremony_type text NOT NULL,
    session_data_encrypted text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT webauthn_ceremonies_ceremony_type_check CHECK ((ceremony_type = ANY (ARRAY['registration'::text, 'login'::text]))),
    CONSTRAINT webauthn_ceremonies_token_hash_check CHECK ((length(token_hash) = 64)),
    CONSTRAINT webauthn_ceremony_owner CHECK ((((ceremony_type = 'registration'::text) AND (mfa_login_transaction_id IS NULL)) OR ((ceremony_type = 'login'::text) AND (mfa_login_transaction_id IS NOT NULL))))
);

ALTER TABLE ONLY public.webauthn_ceremonies FORCE ROW LEVEL SECURITY;


--
-- Name: webauthn_credentials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webauthn_credentials (
    device_id uuid NOT NULL,
    user_id uuid NOT NULL,
    credential_id bytea NOT NULL,
    credential_encrypted text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT webauthn_credentials_credential_id_check CHECK ((octet_length(credential_id) > 0))
);

ALTER TABLE ONLY public.webauthn_credentials FORCE ROW LEVEL SECURITY;


--
-- Name: webhook_deliveries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subscription_id uuid NOT NULL,
    event_type text NOT NULL,
    payload text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    http_status integer,
    response_body text,
    attempts integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    delivered_at timestamp with time zone,
    event_id uuid NOT NULL,
    outbox_event_id uuid,
    last_attempt_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT webhook_deliveries_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text])))
);

ALTER TABLE ONLY public.webhook_deliveries FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE webhook_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.webhook_deliveries IS 'Customer-visible webhook history; generic job tables exclusively own execution lifecycle';


--
-- Name: COLUMN webhook_deliveries.attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.attempts IS 'Latest generic-job attempt projected for customer-visible history';


--
-- Name: webhook_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    url text NOT NULL,
    secret_encrypted text NOT NULL,
    events text[] DEFAULT '{}'::text[] NOT NULL,
    active boolean DEFAULT true NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    previous_secret_encrypted text,
    previous_secret_expires_at timestamp with time zone,
    CONSTRAINT webhook_previous_secret_pair CHECK ((((previous_secret_encrypted IS NULL) AND (previous_secret_expires_at IS NULL)) OR ((previous_secret_encrypted IS NOT NULL) AND (previous_secret_expires_at IS NOT NULL))))
);

ALTER TABLE ONLY public.webhook_subscriptions FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN webhook_subscriptions.secret_encrypted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_subscriptions.secret_encrypted IS 'Versioned Vault/KMS envelope; never plaintext after accounts startup';


--
-- Name: COLUMN webhook_subscriptions.previous_secret_encrypted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_subscriptions.previous_secret_encrypted IS 'Prior Vault/KMS envelope, accepted only until previous_secret_expires_at';


--
-- Name: work_context_replay; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_context_replay (
    org_id uuid NOT NULL,
    context_id text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.work_context_replay FORCE ROW LEVEL SECURITY;


