REVOKE CREATE ON SCHEMA public FROM app_control_plane;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
DO $database_acl$ BEGIN
 EXECUTE format('REVOKE TEMPORARY ON DATABASE %I FROM PUBLIC', current_database());
END $database_acl$;

-- Preserve migration 97's install-time partition window.
DO $partitions$ DECLARE m int; BEGIN
 FOR m IN -2..3 LOOP
  PERFORM public.audit_events_ensure_partition((date_trunc('month', now()) + (m || ' month')::interval)::date);
 END LOOP;
END $partitions$;
ALTER TABLE public.audit_events
    ADD CONSTRAINT audit_events_impersonation_identity_complete CHECK (((is_impersonated AND (impersonated_by IS NOT NULL)) OR ((NOT is_impersonated) AND (impersonated_by IS NULL)))) NOT VALID;
GRANT SELECT, UPDATE, USAGE ON SEQUENCE public.job_state_transitions_sequence_seq TO CURRENT_USER;
SET row_security = on;
SET check_function_bodies = on;
